            if grid[r][c] in (0, 8) or (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            motif = []
            while q:
                y, x = q.popleft()
                motif.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color
                            and (yy, xx) not in seen):
                        seen.add((yy, xx))
                        q.append((yy, xx))
            # Locate the zero field adjacent to this colored seed; its connected
