            neighbors = []
            for y, x in motif:
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 0:
                        neighbors.append((yy, xx))
            zseen = set()
            zero_cells = []
            for start in neighbors:
                if start in zseen:
                    continue
                q = deque([start])
                zseen.add(start)
                comp = []
                while q:
                    y, x = q.popleft()
                    comp.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        yy, xx = y + dy, x + dx
                        if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 0 and (yy, xx) not in zseen:
