def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    # Each colored seed is a motif; it tiles the adjacent zero rectangle with its
    # bounding rectangle, including zero holes inside that motif.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (0, 8) or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            motif = []
            while q:
                y, x = q.popleft()
                motif.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            mr0, mr1 = min(y for y, _ in motif), max(y for y, _ in motif)
            mc0, mc1 = min(x for _, x in motif), max(x for _, x in motif)
            mh, mw = mr1-mr0+1, mc1-mc0+1
            # Fill each adjacent zero component by repeating the seed pattern,
            # aligned to the seed's top-left, preserving zeros in motif holes.
            zseen = set()
            for y, x in motif:
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    sy, sx = y+dy, x+dx
                    if not (0 <= sy < h and 0 <= sx < w) or grid[sy][sx] != 0 or (sy, sx) in zseen:
                        continue
                    q = deque([(sy, sx)])
                    zseen.add((sy, sx))
                    comp = []
                    while q:
                        yy, xx = q.popleft()
                        comp.append((yy, xx))
                        for ddy, ddx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                            ny, nx = yy+ddy, xx+ddx
                            if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 0 and (ny, nx) not in zseen:
                                zseen.add((ny, nx))
                                q.append((ny, nx))
                    for yy, xx in comp:
                        iy, ix = mr0 + (yy-mr0) % mh, mc0 + (xx-mc0) % mw
                        if grid[iy][ix] == color:
                            out[yy][xx] = color
    return out
